={{ (() => {
  const q = $('Prepare question').first().json;
  // Only this workspace's documents can ever be returned.
  const filter = { must: [{ key: 'workspace_id', match: { value: q.workspaceId } }] };
  return JSON.stringify({
    prefetch: [
      { query: $json.data[0].embedding, using: 'dense', limit: 40, filter },
      { query: q.keywords, using: 'bm25', limit: 40, filter },
    ],
    query: { fusion: 'rrf' }, // merge both result lists
    limit: q.passagesToUse,
    with_payload: true,
  });
})() }}

