// Turn the search results into labelled excerpts the model can cite.
const q = $('Prepare question').first().json;
const hits = $json.result?.points ?? [];

const excerpts = hits
  // Read in document order: file, then page, then position on the page.
  .sort((a, b) =>
    a.payload.file_name.localeCompare(b.payload.file_name) ||
    a.payload.page_number - b.payload.page_number ||
    a.payload.chunk_index - b.payload.chunk_index)
  .map((hit) => `[${hit.payload.file_name}, p. ${hit.payload.page_number}]\n${hit.payload.text}`)
  .join('\n\n---\n\n');

const history = q.history
  .slice(-10)
  .map((turn) => `${turn.role === 'user' ? 'CEO' : 'Assistant'}: ${turn.content}`)
  .join('\n\n');

const prompt = [
  history && `Conversation so far:\n${history}`,
  `Documents in this workspace: ${q.documentNames.join(', ') || '(none)'}`,
  q.keyFacts && `Key dates and facts (read from the documents):\n${q.keyFacts}`,
  `Excerpts from the documents (the most relevant passages, in file and page order):\n\n${excerpts || '(no matching passages were found)'}`,
  `CEO's question: ${q.question}`,
].filter(Boolean).join('\n\n=====\n\n');

return [{ json: {
  prompt,
  systemPrompt: q.systemPrompt,
  model: q.model,
  reasoningEffort: q.reasoningEffort,
  passagesFound: hits.length,
} }];
